1	#!/usr/bin/env bash
2	# GRPO | vision | vLLM rollout | FSDP training | GPU/NPU
3	# Canonical Qwen3-VL baseline on Geo3K.
4	
5	set -xeuo pipefail
6	
7	########################### user-adjustable ###########################
8	# DEVICE is auto-detected by probing torch_npu; override only for special cases.
9	DEVICE=${DEVICE:-$(python3 -c 'import torch_npu' 2>/dev/null && echo npu || echo gpu)}
10	MODEL_PATH=${MODEL_PATH:-Qwen/Qwen3-VL-8B-Instruct}
11	NNODES=${NNODES:-1}
12	NDEVICES_PER_NODE=${NDEVICES_PER_NODE:-}
13	
14	TRAIN_BATCH_SIZE=${TRAIN_BATCH_SIZE:-512}
15	PPO_MINI_BATCH_SIZE=${PPO_MINI_BATCH_SIZE:-128}
16	MAX_PROMPT_LENGTH=${MAX_PROMPT_LENGTH:-1024}
17	MAX_RESPONSE_LENGTH=${MAX_RESPONSE_LENGTH:-2048}
18	PPO_MAX_TOKEN_LEN_PER_GPU=${PPO_MAX_TOKEN_LEN_PER_GPU:-24576}
19	
20	ACTOR_LR=${ACTOR_LR:-1e-6}
21	KL_LOSS_COEF=${KL_LOSS_COEF:-0.01}
22	ENTROPY_COEFF=${ENTROPY_COEFF:-0}
23	
24	ROLLOUT_TP=${ROLLOUT_TP:-2}
25	ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-}
26	ROLLOUT_N=${ROLLOUT_N:-5}
27	SP_SIZE=${SP_SIZE:-1}
28	
29	TOTAL_EPOCHS=${TOTAL_EPOCHS:-15}
30	SAVE_FREQ=${SAVE_FREQ:-20}
31	TEST_FREQ=${TEST_FREQ:-5}
32	
33	PROJECT_NAME=${PROJECT_NAME:-verl_grpo_geo3k}
34	EXPERIMENT_NAME=${EXPERIMENT_NAME:-qwen3_vl_8b_grpo_vllm_fsdp_$(date +%Y%m%d_%H%M)}
35	
36	TRAIN_FILE=${TRAIN_FILE:-$HOME/data/geo3k/train.parquet}
37	TEST_FILE=${TEST_FILE:-$HOME/data/geo3k/test.parquet}
38	########################### end user-adjustable ###########################
39	
40	########################### derived defaults ###########################
41	n_devices_per_node=${NDEVICES_PER_NODE:-8}
42	
43	case "${DEVICE}" in
44	    gpu)
45	        rollout_gpu_mem_util=${ROLLOUT_GPU_MEM_UTIL:-0.6}
46	        ;;
47	    npu)
48	        export HCCL_CONNECT_TIMEOUT=1500
49	        export HCCL_HOST_SOCKET_PORT_RANGE=60000-60050
50	        export HCCL_NPU_SOCKET_PORT_RANGE=61000-61050
51	        export RAY_EXPERIMENTAL_NOSET_ASCEND_RT_VISIBLE_DEVICES=1
52	
53	        rollout_gpu_mem_util=${ROLLOUT_GPU_MEM_UTIL:-0.5}
54	        ;;
55	    *)
56	        echo "Unsupported DEVICE=${DEVICE}. Expected 'gpu' or 'npu'." >&2
57	        exit 1
58	        ;;
59	esac
60	
61	########################### parameter arrays ###########################
62	
63	DATA=(
64	    algorithm.adv_estimator=grpo
65	    algorithm.use_kl_in_reward=False
66	    data.train_files=${TRAIN_FILE}
67	    data.val_files=${TEST_FILE}
68	    data.image_key=images
69	    data.train_batch_size=${TRAIN_BATCH_SIZE}
70	    data.max_prompt_length=${MAX_PROMPT_LENGTH}
71	    data.max_response_length=${MAX_RESPONSE_LENGTH}
72	    data.filter_overlong_prompts=True
73	    data.truncation='error'
74	)
75	
76	MODEL=(
77	    actor_rollout_ref.model.path="$MODEL_PATH"
78	    actor_rollout_ref.model.use_remove_padding=True
79	    actor_rollout_ref.model.enable_gradient_checkpointing=True
80	)
81	
82	ACTOR=(
83	    actor_rollout_ref.actor.strategy=fsdp2
84	    actor_rollout_ref.actor.optim.lr=${ACTOR_LR}
85	    actor_rollout_ref.actor.ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE}
86	    actor_rollout_ref.actor.use_dynamic_bsz=True
87	    actor_rollout_ref.actor.ppo_max_token_len_per_gpu=${PPO_MAX_TOKEN_LEN_PER_GPU}
88	    actor_rollout_ref.actor.use_kl_loss=True
89	    actor_rollout_ref.actor.kl_loss_coef=${KL_LOSS_COEF}
90	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
91	    actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
92	)
93	
94	ROLLOUT=(
95	    actor_rollout_ref.rollout.name=vllm
96	    actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TP}
97	    actor_rollout_ref.rollout.gpu_memory_utilization=${rollout_gpu_mem_util}
98	    actor_rollout_ref.rollout.enable_chunked_prefill=False
99	    actor_rollout_ref.rollout.n=${ROLLOUT_N}
100	    actor_rollout_ref.rollout.log_prob_use_dynamic_bsz=True
101	    actor_rollout_ref.rollout.log_prob_max_token_len_per_gpu=${PPO_MAX_TOKEN_LEN_PER_GPU}
102	)
103	
104	REF=(
105	    actor_rollout_ref.ref.log_prob_use_dynamic_bsz=True
106	    actor_rollout_ref.ref.log_prob_max_token_len_per_gpu=${PPO_MAX_TOKEN_LEN_PER_GPU}
107	    actor_rollout_ref.ref.fsdp_config.param_offload=True
108	)
109	
110	TRAINER=(
111	    trainer.balance_batch=True
112	    trainer.logger='["console","wandb"]'
113	    trainer.project_name=${PROJECT_NAME}
114	    trainer.experiment_name=${EXPERIMENT_NAME}
115	    trainer.n_gpus_per_node=${n_devices_per_node}
116	    trainer.nnodes=${NNODES}
117	    trainer.save_freq=${SAVE_FREQ}
118	    trainer.test_freq=${TEST_FREQ}
119	    trainer.total_epochs=${TOTAL_EPOCHS}
120	)
121	
122	# Per-device extras (single trailing array, never empty).
123	if [ "${DEVICE}" = npu ]; then
124	    EXTRA=(
125	        actor_rollout_ref.actor.use_torch_compile=False
126	        actor_rollout_ref.actor.fsdp_config.param_offload=True
127	        actor_rollout_ref.actor.fsdp_config.optimizer_offload=True
128	        actor_rollout_ref.actor.fsdp_config.ulysses_sequence_parallel_size=${SP_SIZE}
129	        actor_rollout_ref.ref.fsdp_config.ulysses_sequence_parallel_size=${SP_SIZE}
130	        +actor_rollout_ref.rollout.engine_kwargs.vllm.mm_processor_cache_gb=0
131	        actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=20
132	    )
133	else
134	    EXTRA=(
135	        actor_rollout_ref.model.use_fused_kernels=True
136	        actor_rollout_ref.actor.fsdp_config.param_offload=False
